const staticData = $getWorkflowStaticData('global');
staticData.counters = {
  us_only: 0,
  eu_uk_europe_only: 0,
  hybrid_onsite: 0,
  timezone_risk: 0,
  low_score: 0,
};
staticData.runDate = new Date().toISOString().slice(0, 10);
return [{ json: { started: true, run_date: staticData.runDate } }];

const items = $input.all();
const raw = items[0]?.json;
const list = Array.isArray(raw) ? raw : (raw?.body || raw?.data || []);
const jobs = list.filter(j => j && j.id && j.position);
const out = jobs.map(j => {
  const tags = Array.isArray(j.tags) ? j.tags : [];
  return {
    job_title: j.position || '',
    company: j.company || '',
    job_url: j.url || (j.slug ? `https://remoteok.com/remote-jobs/${j.slug}` : ''),
    source: 'RemoteOK',
    location_text: j.location || 'Worldwide',
    salary: (j.salary_min || j.salary_max) ? `${j.salary_min || ''}-${j.salary_max || ''}` : '',
    description: (j.description || '').replace(/<[^>]*>/g, ' ').slice(0, 6000),
    posted_date: j.date || '',
    tags: tags.join(', '),
  };
});
return out.map(j => ({ json: j }));

const items = $input.all();
const body = items[0]?.json;
const jobs = body?.jobs || [];
const out = jobs.map(j => ({
  job_title: j.title || '',
  company: j.company_name || '',
  job_url: j.url || '',
  source: 'Remotive',
  location_text: j.candidate_required_location || 'Worldwide',
  salary: j.salary || '',
  description: (j.description || '').replace(/<[^>]*>/g, ' ').slice(0, 6000),
  posted_date: j.publication_date || '',
  tags: Array.isArray(j.tags) ? j.tags.join(', ') : '',
}));
return out.map(j => ({ json: j }));

const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  const titleRaw = j.title || '';
  let company = '', title = titleRaw;
  const parts = titleRaw.split(':');
  if (parts.length > 1) {
    company = parts[0].trim();
    title = parts.slice(1).join(':').trim();
  }
  return {
    job_title: title,
    company: company,
    job_url: j.link || j.guid || '',
    source: 'We Work Remotely',
    location_text: 'See description',
    salary: '',
    description: (j.contentSnippet || j.content || j.summary || '').slice(0, 6000),
    posted_date: j.isoDate || j.pubDate || '',
    tags: Array.isArray(j.categories) ? j.categories.join(', ') : '',
  };
});
return out.map(j => ({ json: j }));

const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  return {
    job_title: j.title || '',
    company: (j.creator || j.author || '').toString(),
    job_url: j.link || j.guid || '',
    source: 'Himalayas',
    location_text: 'See description',
    salary: '',
    description: (j.contentSnippet || j.content || '').slice(0, 6000),
