    tags: Array.isArray(j.categories) ? j.categories.join(', ') : '',
  };
});
return out.map(j => ({ json: j }));

const KEYWORDS = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote', 'work from anywhere',
  'remote data analyst', 'remote data scientist', 'remote ai marketing', 'remote marketing analyst',
  'remote growth analyst', 'remote bi analyst', 'remote automation specialist', 'remote ai workflow consultant',
  'data analyst', 'data scientist', 'marketing analyst', 'growth analyst', 'business intelligence',
  'automation specialist', 'ai workflow', 'performance marketing', 'martech',
];
const items = $input.all();
const matched = items.filter(item => {
  const j = item.json;
  const haystack = `${j.job_title} ${j.description} ${j.tags}`.toLowerCase();
  return KEYWORDS.some(k => haystack.includes(k));
});
return matched;

const existing = $('Get Existing Job URLs').all().map(i => i.json);
const urlSet = new Set(existing.map(e => (e.job_url || '').trim().toLowerCase()).filter(Boolean));
const compSet = new Set(existing.map(e => `${(e.company || '').trim().toLowerCase()}|${(e.job_title || '').trim().toLowerCase()}`).filter(k => k !== '|'));

function makeId(url, title, company) {
  const str = (url || `${company}-${title}`).toLowerCase();
  let hash = 0;
  for (let i = 0; i < str.length; i++) { hash = (hash * 31 + str.charCodeAt(i)) >>> 0; }
  return `job_${hash}`;
}

const items = $input.all();
const seenThisRun = new Set();
const fresh = [];
for (const item of items) {
  const j = item.json;
  const url = (j.job_url || '').trim().toLowerCase();
  const key = `${(j.company || '').trim().toLowerCase()}|${(j.job_title || '').trim().toLowerCase()}`;
  if (!url && key === '|') continue;
  if (url && urlSet.has(url)) continue;
  if (compSet.has(key)) continue;
  if (seenThisRun.has(url || key)) continue;
  seenThisRun.add(url || key);
  j.job_id = makeId(j.job_url, j.job_title, j.company);
  j.date_found = new Date().toISOString().slice(0, 10);
  j.notes = '';
  fresh.push({ json: j });
}
return fresh;

const REJECT_PHRASES = [
  'us only', 'united states only', 'canada only', 'uk only', 'united kingdom only', 'eu only', 'europe only', 'australia only',
  'must be based in', 'must live in', 'must be authorized to work in', 'local work permit required',
  'hybrid', 'onsite', 'on-site', 'office required', 'remote within', 'fixed us hours', 'fixed eu hours',
];
const KEEP_PHRASES = [
  'worldwide remote', 'global remote', 'work from anywhere', 'remote anywhere', 'anywhere in the world',
  'apac remote', 'international contractors', 'contractor role', 'b2b contractor', 'hires via deel',
  'hires via remote.com', 'hires via oyster', 'eor supported', 'remote first', 'distributed team',
];
const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  const haystack = `${j.job_title} ${j.location_text} ${j.description}`.toLowerCase();
  const rejectHit = REJECT_PHRASES.find(p => haystack.includes(p));
  const keepHit = KEEP_PHRASES.find(p => haystack.includes(p));
  let hard_pass = true;
  let hard_reject_reason = '';
  if (rejectHit && !keepHit) {
    hard_pass = false;
    hard_reject_reason = rejectHit;
  }
  j.hard_pass = hard_pass;
  j.hard_reject_reason = hard_reject_reason;
  j.keep_signal_matched = keepHit || '';
  return { json: j };
});
return out;

const staticData = $getWorkflowStaticData('global');
const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  const reason = (j.hard_reject_reason || '').toLowerCase();
  let bucket = 'hybrid_onsite';
  if (reason.includes('us only') || reason.includes('united states')) bucket = 'us_only';
  else if (reason.includes('uk') || reason.includes('eu') || reason.includes('europe') || reason.includes('canada') || reason.includes('australia')) bucket = 'eu_uk_europe_only';
  else if (reason.includes('fixed')) bucket = 'timezone_risk';
  staticData.counters[bucket] = (staticData.counters[bucket] || 0) + 1;
  j.date_rejected = new Date().toISOString().slice(0, 10);
  j.reason = `Location filter: ${j.hard_reject_reason}`;
  return { json: j };
});
return out;

const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  let aiText = '';
  try { aiText = j.content?.[0]?.text || ''; } catch (e) { aiText = ''; }
  let parsed = null;
  try {
    const match = aiText.match(/\{[\s\S]*\}/);
    parsed = match ? JSON.parse(match[0]) : null;
  } catch (e) { parsed = null; }
  if (!parsed) {
    parsed = { taiwan_eligible: 'unclear', reason: 'AI response could not be parsed', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
  }
  const ai_pass = !(parsed.taiwan_eligible === 'no' || parsed.decision === 'reject' || parsed.location_risk === 'high');
  return {
    json: {
      ...j,
      taiwan_eligible: parsed.taiwan_eligible,
      taiwan_reason: parsed.reason,
      location_risk: parsed.location_risk,
      timezone_risk: parsed.timezone_risk,
      contractor_possible: parsed.contractor_possible,
      ai_decision: parsed.decision,
      ai_pass: ai_pass,
    },
  };
});
return out;

const staticData = $getWorkflowStaticData('global');
const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  const reasonText = (j.taiwan_reason || '').toLowerCase();
  let bucket = 'hybrid_onsite';
  if (reasonText.includes('us') || reasonText.includes('united states')) bucket = 'us_only';
  else if (reasonText.includes('uk') || reasonText.includes('eu') || reasonText.includes('europe') || reasonText.includes('canada') || reasonText.includes('australia')) bucket = 'eu_uk_europe_only';
  else if (reasonText.includes('hour') || reasonText.includes('timezone') || reasonText.includes('overnight') || reasonText.includes('night')) bucket = 'timezone_risk';
  staticData.counters[bucket] = (staticData.counters[bucket] || 0) + 1;
  j.date_rejected = new Date().toISOString().slice(0, 10);
  j.reason = `AI Taiwan eligibility check: ${j.taiwan_reason} (taiwan_eligible=${j.taiwan_eligible}, decision=${j.ai_decision})`;
  return { json: j };
});
return out;

const ASYNC_KEEP = ['async', 'asynchronous', 'flexible hours', 'flexible schedule', 'distributed team', 'remote first', 'low meeting culture', 'work across time zones'];
const ASYNC_REJECT = ['strict 9 to 5', 'strict 9-5', 'fixed us hours', 'fixed est hours', 'fixed pst hours', 'fixed cet hours', 'daily live calls required', 'must overlap full business day'];
const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  const haystack = `${j.description} ${j.job_title}`.toLowerCase();
  const asyncHits = ASYNC_KEEP.filter(p => haystack.includes(p));
  const rejectHits = ASYNC_REJECT.filter(p => haystack.includes(p));
  let async_level = 'low';
  if (asyncHits.some(h => h.includes('async'))) async_level = 'high';
  else if (asyncHits.length >= 1) async_level = 'medium';
  const timezone_risk_final = rejectHits.length > 0 ? 'high' : (j.timezone_risk || 'low');
  j.async_level = async_level;
  j.async_keywords_matched = asyncHits.join(', ');
  j.async_reject_matched = rejectHits.join(', ');
  j.timezone_risk_final = timezone_risk_final;
  return { json: j };
});
return out;

const staticData = $getWorkflowStaticData('global');
const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  staticData.counters.timezone_risk = (staticData.counters.timezone_risk || 0) + 1;
  j.date_rejected = new Date().toISOString().slice(0, 10);
  j.reason = `Timezone risk: ${j.async_reject_matched || 'fixed working hours incompatible with Taiwan time'}`;
  return { json: j };
});
return out;

const CORE_ROLES = ['data analyst', 'data scientist', 'junior data scientist', 'business intelligence analyst', 'bi analyst', 'marketing analyst', 'performance marketing analyst', 'growth analyst', 'ai marketing specialist', 'ai automation specialist', 'ai workflow consultant', 'martech analyst', 'creative strategist'];
const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  const haystack = `${j.job_title} ${j.description} ${j.tags}`.toLowerCase();
  const hit = CORE_ROLES.find(r => haystack.includes(r));
  let role_category = hit || (haystack.includes('marketing') ? 'adjacent-marketing' : (haystack.includes('data') || haystack.includes('analytics') ? 'adjacent-data' : 'other'));
  j.role_category = role_category;
  j.role_fit_level = hit ? 'core' : (role_category.startsWith('adjacent') ? 'adjacent' : 'none');
  return { json: j };
});
return out;

const items = $input.all();
function parseMonthlyUSD(text) {
  if (!text) return 0;
  const nums = (text.match(/[\d,]{3,}/g) || []).map(n => parseInt(n.replace(/,/g, ''), 10)).filter(n => n > 0);
  if (!nums.length) return 0;
  const max = Math.max(...nums);
  if (max > 20000) return Math.round(max / 12);
  return max;
}
const out = items.map(item => {
  const j = item.json;
  const combined = `${j.salary} ${j.description}`;
  const monthly = parseMonthlyUSD(combined);
  j.salary_listed = !!(j.salary && j.salary.trim());
  j.salary_monthly_estimate_usd = monthly;
  return { json: j };
});
return out;

const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  let score = 0;
  const kw = (j.keep_signal_matched || '').toLowerCase();
  if (['worldwide remote', 'global remote', 'work from anywhere', 'contractor', 'b2b contractor', 'hires via deel', 'hires via remote.com', 'hires via oyster', 'eor supported'].some(k => kw.includes(k)) || j.taiwan_eligible === 'yes') {
    score += 40;
  } else if (kw.includes('apac')) {
    score += 30;
  } else if (j.taiwan_eligible === 'unclear' && j.location_risk !== 'high') {
    score += 20;
  }
  if (j.async_level === 'high') score += 25;
  else if (j.async_level === 'medium') score += 20;
  if ((j.async_keywords_matched || '').includes('distributed team')) score += 15;
  if ((j.async_keywords_matched || '').includes('remote first')) score += 10;
  if (j.role_fit_level === 'core') score += 25;
  else if (j.role_fit_level === 'adjacent') score += 15;
  if (j.salary_listed) score += 10;
  if (j.salary_monthly_estimate_usd >= 5000) score += 25;
  else if (j.salary_monthly_estimate_usd >= 3000) score += 15;
  j.score = Math.min(100, score);
  return { json: j };
});
return out;

const staticData = $getWorkflowStaticData('global');
const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  staticData.counters.low_score = (staticData.counters.low_score || 0) + 1;
  j.date_rejected = new Date().toISOString().slice(0, 10);
  j.reason = `Score below 70 (scored ${j.score})`;
  return { json: j };
});
return out;

const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  j.timezone_risk = j.timezone_risk_final;
  let decision = 'review';
  if (j.taiwan_eligible === 'yes' && j.score >= 85 && ['high', 'medium'].includes(j.async_level) && j.location_risk === 'low' && ['low', 'medium'].includes(j.timezone_risk_final)) {
    decision = 'apply_immediately';
  } else if (j.taiwan_eligible === 'unclear' && j.score >= 85 && j.location_risk === 'medium') {
    decision = 'manual_check';
  } else if (j.taiwan_eligible === 'no' || j.location_risk === 'high' || j.timezone_risk_final === 'high') {
    decision = 'reject';
  }
  j.decision = decision;
  j.application_status = decision === 'apply_immediately' ? 'ready_to_apply' : (decision === 'manual_check' ? 'needs_manual_review' : 'new');
  j.why_good_fit = `Role fit: ${j.role_category} (${j.role_fit_level}); Async: ${j.async_level}; ${j.taiwan_reason || ''}`.trim();
  j.notes = j.notes || '';
  return { json: j };
});
return out;

const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  let letter = '';
  try { letter = j.content?.[0]?.text || ''; } catch (e) { letter = ''; }
  j.cover_letter_draft = letter;
  j.notes = letter ? `COVER LETTER DRAFT:\n${letter}` : (j.notes || '');
  j.instant_alert_text = [
    `INSTANT ALERT: New Taiwan-eligible job scored ${j.score}/100`,
    '',
    j.job_title,
    `Company: ${j.company}`,
    `Score: ${j.score}`,
    `Taiwan eligible: ${j.taiwan_eligible}`,
    `Reason: ${j.taiwan_reason}`,
    `Async level: ${j.async_level}`,
    `Timezone risk: ${j.timezone_risk_final}`,
    `Salary: ${j.salary || 'not listed'}`,
    `Why it fits Jerry: ${j.why_good_fit}`,
    `Apply link: ${j.job_url}`,
  ].join('\n');
  return { json: j };
});
return out;

const staticData = $getWorkflowStaticData('global');
const agg = $input.first().json;
const jobs = agg.jobs || [];
const sorted = [...jobs].sort((a, b) => (b.score || 0) - (a.score || 0));
const top = sorted.slice(0, 8);
const manualCheck = sorted.filter(j => j.decision === 'manual_check');
const counters = staticData.counters || {};

function jobBlock(j, i) {
  return [
    `${i + 1}. ${j.job_title}`,
    `Company: ${j.company}`,
    `Score: ${j.score}`,
    `Taiwan eligible: ${j.taiwan_eligible}`,
    `Reason: ${j.taiwan_reason}`,
    `Async level: ${j.async_level}`,
    `Timezone risk: ${j.timezone_risk_final}`,
    `Salary: ${j.salary || 'not listed'}`,
    `Why it fits Jerry: ${j.why_good_fit}`,
    `Apply link: ${j.job_url}`,
    '',
  ].join('\n');
}

let message = 'Daily Taiwan Eligible Async Remote Jobs\n\n';
message += 'Top jobs today:\n\n';
message += top.length ? top.map(jobBlock).join('\n') : '(No jobs scored 70+ today.)\n\n';
message += 'Manual check:\n';
message += manualCheck.length
  ? manualCheck.map(j => `- ${j.job_title} at ${j.company} (score ${j.score}) - ${j.job_url}`).join('\n')
  : '(None)';
message += '\n\nRejected summary:\n';
message += `US only: ${counters.us_only || 0}\n`;
message += `EU/UK/Europe/Canada/Australia only: ${counters.eu_uk_europe_only || 0}\n`;
message += `Hybrid/onsite: ${counters.hybrid_onsite || 0}\n`;
message += `Timezone risk: ${counters.timezone_risk || 0}\n`;
message += `Low score (<70): ${counters.low_score || 0}\n`;

return [{ json: { digest_text: message, top_count: top.length, manual_check_count: manualCheck.length } }];
